import unittest
from candidate import same_chars

class TestSameChars(unittest.TestCase):
    def test_same_chars_docstring_example_true(self):
        self.assertTrue(same_chars('eabcdzzzz', 'dddzzzzzzzddeddabc'))

    def test_same_chars_docstring_example_true2(self):
        self.assertTrue(same_chars('abcd', 'dddddddabc'))

    def test_same_chars_docstring_example_true3(self):
        self.assertTrue(same_chars('dddddddabc', 'abcd'))

    def test_same_chars_docstring_example_false1(self):
        self.assertFalse(same_chars('eabcd', 'dddddddabc'))

    def test_same_chars_docstring_example_false2(self):
        self.assertFalse(same_chars('abcd', 'dddddddabce'))

    def test_same_chars_docstring_example_false3(self):
        self.assertFalse(same_chars('eabcdzzzz', 'dddzzzzzzzddddabc'))

    def test_same_chars_identical_strings(self):
        self.assertTrue(same_chars('hello', 'hello'))

    def test_same_chars_empty_strings(self):
        self.assertTrue(same_chars('', ''))

    def test_same_chars_one_empty_one_not(self):
        self.assertFalse(same_chars('', 'a'))

    def test_same_chars_single_same_char(self):
        self.assertTrue(same_chars('a', 'a'))

    def test_same_chars_single_diff_char(self):
        self.assertFalse(same_chars('a', 'b'))

    def test_same_chars_same_char_repeated(self):
        self.assertTrue(same_chars('aaa', 'aaaa'))

    def test_same_chars_all_same_vs_different(self):
        self.assertFalse(same_chars('aaa', 'aab'))

    def test_same_chars_order_independent(self):
        self.assertTrue(same_chars('abc', 'cba'))

    def test_same_chars_case_sensitive(self):
        self.assertFalse(same_chars('A', 'a'))

    def test_same_chars_case_sensitive_both(self):
        self.assertFalse(same_chars('Abc', 'abc'))

    def test_same_chars_with_spaces(self):
        self.assertTrue(same_chars('a b', 'b a'))

    def test_same_chars_with_special_chars(self):
        self.assertTrue(same_chars('a!', '!a'))

    def test_same_chars_with_digits(self):
        self.assertTrue(same_chars('a1', '1a'))

    def test_same_chars_with_unicode(self):
        self.assertTrue(same_chars('éà', 'àé'))

    def test_same_chars_none_first_arg(self):
        with self.assertRaises(TypeError):
            same_chars(None, 'abc')

    def test_same_chars_none_second_arg(self):
        with self.assertRaises(TypeError):
            same_chars('abc', None)

    def test_same_chars_both_none(self):
        with self.assertRaises(TypeError):
            same_chars(None, None)

    def test_same_chars_integer_input(self):
        with self.assertRaises(TypeError):
            same_chars(123, 'abc')

    def test_same_chars_string_and_int(self):
        with self.assertRaises(TypeError):
            same_chars('abc', 123)

    def test_same_chars_very_long_strings(self):
        self.assertTrue(same_chars('a' * 10000 + 'b', 'b' * 10000 + 'a'))

    def test_same_chars_all_unique_vs_repeated(self):
        self.assertTrue(same_chars('abcd', 'aaaabbbbccccdddd'))

    def test_same_chars_subset(self):
        self.assertFalse(same_chars('abc', 'ab'))

    def test_same_chars_superset(self):
        self.assertFalse(same_chars('ab', 'abc'))

    def test_same_chars_only_spaces(self):
        self.assertTrue(same_chars(' ', '   '))

    def test_same_chars_newline_tab(self):
        self.assertTrue(same_chars('\n\t', '\t\n'))

    if __name__ == '__main__':
        unittest.main()
